-- >>>>>>>>>> 20261016000000_delivery_pins_app_only.sql <<<<<<<<<<
-- =============================================================================
-- Melai Nuts — Migration 20261016000000: delivery pins (app only)
-- =============================================================================
-- Run after 20261015000000_refunds_in_analytics.sql. Idempotent (create or
-- replace / if not exists), one transaction. No table is dropped and no
-- existing function changes its arguments or its JSON keys.
--
-- Delivery now lives only in the Melai Nuts app (the admin website has no
-- delivery pages any more). The app shows a map wherever a delivery location
-- matters: the customer pins it, staff / owner see it when handling the order
-- and when building a run, the rider sees it for each stop. This migration
-- makes those maps trustworthy:
--
--   1. orders.delivery_latitude / delivery_longitude: the pin is SNAPSHOT on
--      the order when it is placed (a BEFORE INSERT trigger copies it from the
--      customer's saved address, so place_order() itself is unchanged). Staff
--      and the rider therefore see exactly the point the customer confirmed at
--      checkout, even if the customer later edits or deletes that saved
--      address. The address TEXT was already snapshot (delivery_address_text).
--      Once set, the order's pin cannot be changed. Open delivery orders that
--      exist today are backfilled from their saved address; finished orders
--      are left alone (no new personal data is written for them).
--   2. A pin at 0,0 ("null island", what a broken GPS fix returns) is refused
--      for new and edited saved addresses (NOT VALID: old rows are untouched)
--      and never snapshot onto an order.
--   3. _delivery_to_jsonb (stops of a run), staff_list_deliverable_orders
--      (orders to put on a run) and customer_get_delivery_tracking read the
--      order's snapshot first and fall back to the saved address only for
--      orders placed before this migration. staff_list_deliverable_orders also
--      returns latitude / longitude so staff can see every candidate's pin.
--   4. _delivery_for_driver is STRICTER, never weaker: besides hiding address,
--      coordinates, phone and notes once the run is completed / cancelled (as
--      before), a stop's details are now also hidden as soon as THAT stop is
--      delivered, failed or skipped.
--   5. NEW staff_order_delivery_pins(order_ids): the customer's pin, address,
--      contact and the branch position for delivery orders, for the staff
--      order screen. Staff: only orders of their own branch (others are left
--      out); owner: every branch; riders, customers and anon: refused.
--
-- Who can read a pin (enforced here and by the existing RLS):
--   customer  their own saved addresses (RLS "customer: own addresses") and
--             their own orders (RLS "customer: read own orders")
--   rider     only stops of runs assigned to them, only while the stop and the
--             run are still open (_delivery_for_driver)
--   staff     orders / runs of their own branch (RLS "staff: read branch
--             orders", _require_staff + branch checks in every RPC)
--   owner     every branch
--   anon      nothing
-- The admin website reads none of this: admin_portal_orders() has no address
-- or coordinates, and the website no longer calls any delivery function.
-- Coordinates are personal data: nothing here logs them.
-- =============================================================================
begin;

-- -----------------------------------------------------------------------------
-- 1. Snapshot columns on the order
-- -----------------------------------------------------------------------------
alter table public.orders add column if not exists delivery_latitude double precision;
alter table public.orders add column if not exists delivery_longitude double precision;
alter table public.orders drop constraint if exists orders_delivery_pin_valid;
alter table public.orders add constraint orders_delivery_pin_valid check (
  (delivery_latitude is null and delivery_longitude is null)
  or (delivery_latitude between -90 and 90 and delivery_longitude between -180 and 180
      and not (delivery_latitude = 0 and delivery_longitude = 0))
);

-- A saved address may not be pinned at exactly 0,0 (a failed GPS fix, never a
-- Melai Nuts customer). NOT VALID: rows that already exist are not re-checked.
alter table public.customer_addresses drop constraint if exists customer_addresses_not_null_island;
alter table public.customer_addresses add constraint customer_addresses_not_null_island check (
  latitude is null or longitude is null or not (latitude = 0 and longitude = 0)
) not valid;

-- Copies the customer's pin onto a new delivery order. Only the customer's OWN
-- address is ever read (place_order already refuses someone else's address).
create or replace function public._trg_order_snapshot_delivery_pin()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_lat double precision;
  v_lng double precision;
begin
  if new.is_delivery and new.delivery_address_id is not null and new.delivery_latitude is null then
    select latitude, longitude into v_lat, v_lng
    from public.customer_addresses
    where id = new.delivery_address_id and firebase_uid = new.firebase_uid;
    if v_lat is not null and v_lng is not null and not (v_lat = 0 and v_lng = 0) then
      new.delivery_latitude := v_lat;
      new.delivery_longitude := v_lng;
    end if;
  end if;
  if not coalesce(new.is_delivery, false) then
    new.delivery_latitude := null;
    new.delivery_longitude := null;
  end if;
  return new;
end;
$$;

drop trigger if exists orders_snapshot_delivery_pin on public.orders;
create trigger orders_snapshot_delivery_pin
  before insert on public.orders
  for each row execute function public._trg_order_snapshot_delivery_pin();

-- The pin is part of what the customer confirmed: once set it never moves.
create or replace function public._trg_order_pin_immutable()
returns trigger
language plpgsql
as $$
begin
  if old.delivery_latitude is not null
     and (new.delivery_latitude, new.delivery_longitude) is distinct from (old.delivery_latitude, old.delivery_longitude) then
    raise exception 'The delivery pin of order % cannot be changed after it is placed.', old.id;
  end if;
  return new;
end;
$$;

drop trigger if exists orders_pin_immutable on public.orders;
create trigger orders_pin_immutable
  before update of delivery_latitude, delivery_longitude on public.orders
  for each row execute function public._trg_order_pin_immutable();

-- Backfill: open delivery orders only (they may still be put on a run).
update public.orders o
set delivery_latitude = ca.latitude, delivery_longitude = ca.longitude
from public.customer_addresses ca
where ca.id = o.delivery_address_id
  and ca.firebase_uid = o.firebase_uid
  and o.is_delivery
  and o.delivery_latitude is null
  and o.status in ('pending', 'confirmed', 'preparing', 'readyForPickup', 'outForDelivery')
  and ca.latitude is not null and ca.longitude is not null
  and not (ca.latitude = 0 and ca.longitude = 0);

-- -----------------------------------------------------------------------------
-- 2. Read model of a run: the order's snapshot first (same keys as before)
-- -----------------------------------------------------------------------------
create or replace function public._delivery_to_jsonb(p_delivery_id text)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', d.id,
    'branch', d.branch_name,
    'branch_id', d.branch_id,
    'vehicle', d.vehicle,
    'rider_name', d.rider_name,
    'status', d.status,
    'created_at', d.created_at,
    'driver_uid', d.driver_uid,
    'driver_status', d.driver_status,
    'driver_phone', dr.phone,
    'assigned_at', d.assigned_at,
    'accepted_at', d.accepted_at,
    'picked_up_at', d.picked_up_at,
    'completed_at', d.completed_at,
    'tracking_active', d.tracking_active,
    'branch_latitude', b.latitude,
    'branch_longitude', b.longitude,
    'stops', (
      select coalesce(jsonb_agg(to_jsonb(s) order by s.sequence_index), '[]'::jsonb)
      from (
        select
          ds.id,
          o.id as order_id,
          coalesce(nullif(cp.full_name, ''), 'Customer') as customer_name,
          coalesce(o.delivery_address_text, 'Address not provided') as address,
          case when o.delivery_latitude is not null then o.delivery_latitude
               when ca.latitude = 0 and ca.longitude = 0 then null else ca.latitude end as latitude,
          case when o.delivery_latitude is not null then o.delivery_longitude
               when ca.latitude = 0 and ca.longitude = 0 then null else ca.longitude end as longitude,
          o.contact_phone,
          o.customer_notes,
          o.total as order_total,
          p.method as payment_method,
          p.status as payment_status,
          ds.sequence_index,
          ds.distance_from_previous_km,
          ds.travel_minutes_from_previous,
          ds.eta_label as eta,
          ds.status,
          ds.issue_reason,
          ds.proof_note,
          ds.proof_photo_path,
          ds.recipient_name,
          ds.delivered_at,
          ds.failed_at,
          (select coalesce(jsonb_agg(
                     oi.quantity::text || 'x ' || oi.product_name ||
                     case when oi.variant_label is null or oi.variant_label = '' or oi.variant_label = 'Regular'
                          then '' else ' (' || oi.variant_label || ')' end
                   ), '[]'::jsonb)
           from public.order_items oi where oi.order_id = o.id) as items
        from public.delivery_stops ds
        join public.orders o on o.id = ds.order_id
        left join public.customer_profiles cp on cp.firebase_uid = o.firebase_uid
        left join public.customer_addresses ca on ca.id = o.delivery_address_id and ca.firebase_uid = o.firebase_uid
        left join public.payments p on p.order_id = o.id
        where ds.delivery_id = d.id
      ) s
    )
  )
  from public.deliveries d
  join public.branches b on b.id = d.branch_id
  left join public.drivers dr on dr.firebase_uid = d.driver_uid
  where d.id = p_delivery_id
$$;

-- The rider's view: contact details, address and pin only while the run AND
-- that stop are still open (stricter than 20261010010000, never weaker).
create or replace function public._delivery_for_driver(p_delivery_id text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v jsonb := public._delivery_to_jsonb(p_delivery_id);
  v_status text := v ->> 'status';
  v_run_over boolean := v_status in ('completed', 'cancelled');
begin
  if v is null then
    return null;
  end if;
  v := jsonb_set(v, '{stops}', (
    select coalesce(jsonb_agg(
             case when v_run_over or (s ->> 'status') in ('delivered', 'failed', 'skipped')
                  then s - 'address' - 'latitude' - 'longitude' - 'contact_phone' - 'customer_notes'
                       || jsonb_build_object('address', 'Hidden after delivery', 'latitude', null, 'longitude', null)
                  else s end
             order by (s ->> 'sequence_index')::int), '[]'::jsonb)
    from jsonb_array_elements(v -> 'stops') s));
  return v;
end;
$$;

-- -----------------------------------------------------------------------------
-- 3. Orders that can go on a run, with their pins
-- -----------------------------------------------------------------------------
create or replace function public.staff_list_deliverable_orders(p_branch_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_staff public.staff_members;
  v_branch uuid;
begin
  v_staff := public._require_staff();
  v_branch := case when v_staff.role = 'owner' then p_branch_id else v_staff.branch_id end;
  if v_branch is null then raise exception 'Please choose a branch first.'; end if;
  if not (v_branch = any (public.staff_authorized_branch_ids())) then
    raise exception 'You can only work in your assigned branch.';
  end if;

  return (
    select coalesce(jsonb_agg(x.j order by x.created_at), '[]'::jsonb)
    from (
      select o.created_at,
        jsonb_build_object(
          'order_id', o.id,
          'customer_name', coalesce(nullif(cp.full_name, ''), 'Customer'),
          'address', coalesce(o.delivery_address_text, 'Address not provided'),
          'latitude', pin.lat,
          'longitude', pin.lng,
          'contact_phone', o.contact_phone,
          'created_at', o.created_at,
          'items', (select coalesce(jsonb_agg(
                       oi.quantity::text || 'x ' || oi.product_name ||
                       case when oi.variant_label is null or oi.variant_label = '' or oi.variant_label = 'Regular'
                            then '' else ' (' || oi.variant_label || ')' end
                     ), '[]'::jsonb)
                   from public.order_items oi where oi.order_id = o.id)
        ) as j
      from public.orders o
      left join public.customer_profiles cp on cp.firebase_uid = o.firebase_uid
      left join public.customer_addresses ca on ca.id = o.delivery_address_id and ca.firebase_uid = o.firebase_uid
      cross join lateral (
        select case when o.delivery_latitude is not null then o.delivery_latitude
                    when ca.latitude = 0 and ca.longitude = 0 then null else ca.latitude end as lat,
               case when o.delivery_latitude is not null then o.delivery_longitude
                    when ca.latitude = 0 and ca.longitude = 0 then null else ca.longitude end as lng
      ) pin
      where o.branch_id = v_branch
        and o.is_delivery
        and o.status in ('confirmed', 'preparing')
        and not exists (
          select 1 from public.delivery_stops ds
          join public.deliveries d on d.id = ds.delivery_id
          where ds.order_id = o.id and d.status not in ('cancelled', 'completed')
        )
      order by o.created_at
    ) x
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- 4. Staff order screen: where did the customer pin it?
-- -----------------------------------------------------------------------------
create or replace function public.staff_order_delivery_pins(p_order_ids text[])
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_staff public.staff_members;
begin
  v_staff := public._require_staff();   -- riders, customers and anon are refused here
  if p_order_ids is null or cardinality(p_order_ids) = 0 then
    return '[]'::jsonb;
  end if;
  if cardinality(p_order_ids) > 300 then
    raise exception 'Ask for at most 300 orders at a time.';
  end if;

  return (
    select coalesce(jsonb_agg(jsonb_build_object(
             'order_id', o.id,
             'branch_id', o.branch_id,
             'branch_name', b.name,
             'branch_latitude', b.latitude,
             'branch_longitude', b.longitude,
             'address', o.delivery_address_text,
             'recipient_name', coalesce(nullif(ca.recipient_name, ''), nullif(cp.full_name, '')),
             'contact_phone', o.contact_phone,
             'latitude', pin.lat,
             'longitude', pin.lng,
             'pin_snapshot', o.delivery_latitude is not null,
             'distance_km', case when pin.lat is not null and b.latitude is not null and b.longitude is not null
                              then round((6371 * 2 * asin(sqrt(
                                     power(sin(radians(pin.lat - b.latitude) / 2), 2)
                                     + cos(radians(b.latitude)) * cos(radians(pin.lat))
                                       * power(sin(radians(pin.lng - b.longitude) / 2), 2))))::numeric, 2)
                              end
           ) order by o.created_at desc), '[]'::jsonb)
    from public.orders o
    join public.branches b on b.id = o.branch_id
    left join public.customer_profiles cp on cp.firebase_uid = o.firebase_uid
    left join public.customer_addresses ca on ca.id = o.delivery_address_id and ca.firebase_uid = o.firebase_uid
    cross join lateral (
      select case when o.delivery_latitude is not null then o.delivery_latitude
                  when ca.latitude = 0 and ca.longitude = 0 then null else ca.latitude end as lat,
             case when o.delivery_latitude is not null then o.delivery_longitude
                  when ca.latitude = 0 and ca.longitude = 0 then null else ca.longitude end as lng
    ) pin
    where o.id = any (p_order_ids)
      and o.is_delivery
      and (v_staff.role = 'owner' or o.branch_id = v_staff.branch_id)
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- 5. Customer tracking: destination = the pin confirmed on the order
-- -----------------------------------------------------------------------------
create or replace function public.customer_get_delivery_tracking(p_order_id text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid text := public.current_firebase_uid();
  v_order public.orders;
  v_stop public.delivery_stops;
  v_delivery public.deliveries;
  v_branch public.branches;
  v_dest_lat double precision;
  v_dest_lng double precision;
  v_loc_lat double precision;
  v_loc_lng double precision;
  v_loc_at timestamptz;
  v_ahead int;
  v_live boolean;
begin
  if v_uid is null then raise exception 'Please sign in.'; end if;
  select * into v_order from public.orders where id = p_order_id and firebase_uid = v_uid;
  if not found then raise exception 'Order not found.'; end if;
  select * into v_branch from public.branches where id = v_order.branch_id;

  select ds.* into v_stop from public.delivery_stops ds
  join public.deliveries d on d.id = ds.delivery_id
  where ds.order_id = v_order.id and d.status <> 'cancelled'
  order by ds.created_at desc limit 1;
  if v_stop.id is not null then
    select * into v_delivery from public.deliveries where id = v_stop.delivery_id;
  end if;

  if v_order.delivery_latitude is not null then
    v_dest_lat := v_order.delivery_latitude;
    v_dest_lng := v_order.delivery_longitude;
  else
    select latitude, longitude into v_dest_lat, v_dest_lng from public.customer_addresses
    where id = v_order.delivery_address_id and firebase_uid = v_uid
      and not (latitude = 0 and longitude = 0);
  end if;

  v_live := coalesce(v_delivery.id is not null and v_order.status = 'outForDelivery' and v_delivery.tracking_active
                     and v_stop.status in ('pending', 'enRoute', 'delayed'), false);
  if v_live then
    select latitude, longitude, recorded_at into v_loc_lat, v_loc_lng, v_loc_at from public.driver_locations
    where delivery_id = v_delivery.id and recorded_at > now() - interval '10 minutes'
    order by recorded_at desc limit 1;
    select count(*) into v_ahead from public.delivery_stops
    where delivery_id = v_delivery.id and sequence_index < v_stop.sequence_index
      and status not in ('delivered', 'failed', 'skipped');
  end if;

  return jsonb_build_object(
    'order_id', v_order.id,
    'order_status', v_order.status,
    'stop_status', v_stop.status,
    'driver_status', v_delivery.driver_status,
    'driver_name', case when v_live then split_part(coalesce(v_delivery.rider_name, ''), ' ', 1) end,
    'driver_phone', case when v_live then v_order.rider_phone end,
    'eta', v_stop.eta_label,
    'stops_before_you', v_ahead,
    'branch', jsonb_build_object('name', v_branch.name, 'lat', v_branch.latitude, 'lng', v_branch.longitude),
    'destination', jsonb_build_object('lat', v_dest_lat, 'lng', v_dest_lng),
    'driver_location', case when v_loc_at is not null then
        jsonb_build_object('lat', v_loc_lat, 'lng', v_loc_lng, 'recorded_at', v_loc_at) end,
    'tracking_available', v_live and v_loc_at is not null,
    'delivered_at', v_stop.delivered_at
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- 6. Grants
-- -----------------------------------------------------------------------------
revoke all on function public._trg_order_snapshot_delivery_pin() from public, anon, authenticated;
revoke all on function public._trg_order_pin_immutable() from public, anon, authenticated;
revoke all on function public._delivery_to_jsonb(text) from public, anon, authenticated;
revoke all on function public._delivery_for_driver(text) from public, anon, authenticated;

do $g$
declare f text;
begin
  foreach f in array array[
    'public.staff_list_deliverable_orders(uuid)',
    'public.staff_order_delivery_pins(text[])',
    'public.customer_get_delivery_tracking(text)'
  ] loop
    execute 'revoke all on function ' || f || ' from public, anon';
    execute 'grant execute on function ' || f || ' to authenticated';
  end loop;
end
$g$;

commit;


-- >>>>>>>>>> 20261017000000_online_payment_switch.sql <<<<<<<<<<
-- =============================================================================
-- Melai Nuts — Migration 20261017000000: online payment on/off switch
-- =============================================================================
-- Run after 20261016000000_delivery_pins_app_only.sql. Idempotent, one
-- transaction. Nothing is removed: the HitPay code, the
-- 'Online Payment (GCash, Maya, Card)' label in place_order() and every
-- existing order / payment stay exactly as they are.
--
-- Online payment (HitPay: GCash, Maya, card) is switched OFF for customers for
-- now. While it is off:
--   * a NEW customer order with an online payment label is refused by the
--     database (also from older app builds), with a message that tells the
--     customer to pick Cash on Delivery / Cash on Counter Pickup;
--   * the hitpay-create-payment Edge Function refuses to open a payment page
--     (reads the same switch);
--   * in-store POS sales ('GCash (In-store)', 'Card (In-store)', ...) and
--     cash orders are not affected.
--
-- Turn it back on later (SQL editor, as the owner / postgres):
--   update public.payment_settings set online_payment_enabled = true, updated_at = now()
--   where id = 'default';
-- and build the app with --dart-define=ONLINE_PAYMENT_ENABLED=true
-- (see lib/core/config/payment_config.dart).
-- =============================================================================
begin;

create table if not exists public.payment_settings (
  id text primary key default 'default' check (id = 'default'),
  online_payment_enabled boolean not null default false,
  updated_at timestamptz not null default now()
);

insert into public.payment_settings (id, online_payment_enabled)
values ('default', false)
on conflict (id) do nothing;

alter table public.payment_settings enable row level security;

-- Everyone may read the switch (the app can show "temporarily unavailable");
-- nobody but the database owner may change it.
drop policy if exists "anyone reads payment settings" on public.payment_settings;
create policy "anyone reads payment settings" on public.payment_settings
  for select to anon, authenticated using (true);
revoke insert, update, delete on public.payment_settings from anon, authenticated;
grant select on public.payment_settings to anon, authenticated;

create or replace function public.online_payment_enabled()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select online_payment_enabled from public.payment_settings where id = 'default'), false)
$$;

-- Refuses new customer orders paid online while the switch is off.
create or replace function public._trg_orders_online_payment_switch()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.payment_method in ('Online Payment (GCash, Maya, Card)', 'GCash E-Wallet', 'Maya / Credit Card')
     and not public.online_payment_enabled() then
    raise exception 'Online payment is temporarily unavailable. Please choose Cash on Delivery or Cash on Counter Pickup.';
  end if;
  return new;
end;
$$;

drop trigger if exists orders_online_payment_switch on public.orders;
create trigger orders_online_payment_switch
  before insert on public.orders
  for each row execute function public._trg_orders_online_payment_switch();

revoke all on function public._trg_orders_online_payment_switch() from public, anon, authenticated;
revoke all on function public.online_payment_enabled() from public;
grant execute on function public.online_payment_enabled() to anon, authenticated, service_role;

commit;


-- >>>>>>>>>> 20261018000000_business_settings.sql <<<<<<<<<<
-- =============================================================================
-- Melai Nuts — Migration 20261018000000: owner-editable business settings
-- =============================================================================
-- Run after 20261017000000_online_payment_switch.sql. Idempotent, one transaction.
--
-- WHY
--   Several business rules were constants in code: the restock threshold
--   fallback (20, in _default_restock_threshold()), the loyalty earn-rate
--   fallback (1 pt per PHP 50), stock-health and sales-rating ratios and daily
--   sales targets (admin config/melai.php), the "healthy margin" line (50 %,
--   app product screens) and the online-payment "unavailable" text. They are
--   now settings the owner edits (admin website > Settings > Business settings)
--   and that nobody else can change.
--
-- RULES
--   * A setting that was never entered is NULL and is shown as "Not set". No
--     value is invented: without an earn rate no points are earned, without a
--     restock threshold no "low stock" warning is raised (out-of-stock still is),
--     without a target a branch shows "No target set".
--   * On a NEW, empty project this migration creates structure only.
--   * On an EXISTING project that already holds stock (i.e. it ran with the old
--     built-in values), the old values are carried over ONCE, flagged
--     `carried_over = true`, so behaviour does not change silently; the admin
--     page asks the owner to confirm or change them. Re-running never
--     overwrites a value the owner saved.
--   * branches.delivery_fee loses its default of 0: a new branch must be given
--     its real delivery fee (0 only if delivery really is free).
-- =============================================================================
begin;

-- -----------------------------------------------------------------------------
-- 1. Settings table (single row 'default'; every value nullable = "Not set")
-- -----------------------------------------------------------------------------
create table if not exists public.business_settings (
  id text primary key default 'default' check (id = 'default'),
  restock_threshold_default int check (restock_threshold_default is null or restock_threshold_default between 0 and 100000),
  stock_low_ratio numeric(4, 3) check (stock_low_ratio is null or (stock_low_ratio > 0 and stock_low_ratio < 1)),
  stock_plenty_ratio numeric(4, 3) check (stock_plenty_ratio is null or (stock_plenty_ratio > 0 and stock_plenty_ratio <= 1)),
  sales_low_ratio numeric(5, 3) check (sales_low_ratio is null or (sales_low_ratio > 0 and sales_low_ratio <= 10)),
  sales_high_ratio numeric(5, 3) check (sales_high_ratio is null or (sales_high_ratio > 0 and sales_high_ratio <= 10)),
  default_daily_sales_target numeric(12, 2) check (default_daily_sales_target is null or default_daily_sales_target > 0),
  healthy_margin_percent numeric(5, 2) check (healthy_margin_percent is null or (healthy_margin_percent > 0 and healthy_margin_percent < 100)),
  expiry_alert_days int check (expiry_alert_days is null or expiry_alert_days between 1 and 365),
  carried_over boolean not null default false,
  updated_at timestamptz not null default now(),
  updated_by text,
  constraint business_settings_stock_order check (stock_low_ratio is null or stock_plenty_ratio is null or stock_low_ratio < stock_plenty_ratio),
  constraint business_settings_sales_order check (sales_low_ratio is null or sales_high_ratio is null or sales_low_ratio <= sales_high_ratio)
);
alter table public.business_settings enable row level security;
-- No direct table access for the API roles: reads and writes go through the functions below.
revoke all on public.business_settings from anon, authenticated;

-- Per-branch daily sales target (null = use the default target, or "No target set").
alter table public.branches add column if not exists daily_sales_target numeric(12, 2);
alter table public.branches drop constraint if exists branches_daily_sales_target_check;
alter table public.branches add constraint branches_daily_sales_target_check
  check (daily_sales_target is null or daily_sales_target > 0);

-- A branch's delivery fee must be entered, never assumed to be 0.
alter table public.branches alter column delivery_fee drop default;

-- Online payment "unavailable" text lives in the database (the app and the
-- order trigger read it), so it is changed in one place.
alter table public.payment_settings add column if not exists online_payment_disabled_message text;
update public.payment_settings
   set online_payment_disabled_message = 'Online payment is temporarily unavailable. Please choose Cash on Delivery or Cash on Counter Pickup.'
 where id = 'default' and online_payment_disabled_message is null;

-- Carry the old built-in values over ONCE, only on a database that already ran with them.
insert into public.business_settings
  (id, restock_threshold_default, stock_low_ratio, stock_plenty_ratio, sales_low_ratio, sales_high_ratio,
   healthy_margin_percent, carried_over)
select 'default', 20, 0.4, 0.8, 0.7, 1.0, 50, true
where exists (select 1 from public.branch_inventory)
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- 2. Loyalty earn rate: no invented fallback
-- -----------------------------------------------------------------------------
alter table public.loyalty_cart_settings alter column earn_pesos_per_point drop not null;
alter table public.loyalty_cart_settings alter column earn_pesos_per_point drop default;

-- Points earned on an order: floor(total / earn rate). No rate set = 0 points.
create or replace function public.compute_points_earned()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rate numeric;
begin
  select earn_pesos_per_point into v_rate from public.loyalty_cart_settings where id = 'default';
  if v_rate is null or v_rate < 1 then
    new.points_earned := 0;
  else
    new.points_earned := greatest(0, floor(new.total / v_rate)::int);
  end if;
  return new;
end;
$$;

-- NULL when the owner has not set an earn rate (the app shows "Not set").
create or replace function public.get_loyalty_earn_rate()
returns numeric
language sql
stable
security definer
set search_path = public
as $$
  select earn_pesos_per_point from public.loyalty_cart_settings where id = 'default'
$$;
revoke all on function public.get_loyalty_earn_rate() from public;
grant execute on function public.get_loyalty_earn_rate() to anon, authenticated;

-- -----------------------------------------------------------------------------
-- 3. Restock threshold fallback reads the setting (NULL = not set)
-- -----------------------------------------------------------------------------
create or replace function public._default_restock_threshold()
returns int
language sql
stable
security definer
set search_path = public
as $$ select restock_threshold_default from public.business_settings where id = 'default' $$;

-- -----------------------------------------------------------------------------
-- 4. Online payment trigger uses the database text
-- -----------------------------------------------------------------------------
create or replace function public.online_payment_disabled_message()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(nullif(trim((select online_payment_disabled_message from public.payment_settings where id = 'default')), ''),
                  'Online payment is unavailable.')
$$;
revoke all on function public.online_payment_disabled_message() from public;
grant execute on function public.online_payment_disabled_message() to anon, authenticated, service_role;

create or replace function public._trg_orders_online_payment_switch()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.payment_method in ('Online Payment (GCash, Maya, Card)', 'GCash E-Wallet', 'Maya / Credit Card')
     and not public.online_payment_enabled() then
    raise exception '%', public.online_payment_disabled_message();
  end if;
  return new;
end;
$$;
revoke all on function public._trg_orders_online_payment_switch() from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- 5. Read: settings + branches (staff: their own branch; owner: all)
-- -----------------------------------------------------------------------------
create or replace function public.get_business_settings()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_staff public.staff_members;
  s public.business_settings;
  l public.loyalty_cart_settings;
begin
  v_staff := public._require_staff();
  select * into s from public.business_settings where id = 'default';
  select * into l from public.loyalty_cart_settings where id = 'default';
  return jsonb_build_object(
    'restock_threshold_default', s.restock_threshold_default,
    'stock_low_ratio', s.stock_low_ratio,
    'stock_plenty_ratio', s.stock_plenty_ratio,
    'sales_low_ratio', s.sales_low_ratio,
    'sales_high_ratio', s.sales_high_ratio,
    'default_daily_sales_target', s.default_daily_sales_target,
    'healthy_margin_percent', s.healthy_margin_percent,
    'expiry_alert_days', s.expiry_alert_days,
    'carried_over', coalesce(s.carried_over, false),
    'updated_at', s.updated_at,
    'loyalty', jsonb_build_object('earn_pesos_per_point', l.earn_pesos_per_point,
                                  'points_per_peso', l.points_per_peso,
                                  'max_discount_percent', l.max_discount_percent),
    'online_payment_enabled', public.online_payment_enabled(),
    'online_payment_disabled_message', public.online_payment_disabled_message(),
    'branches', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', b.id, 'name', b.name, 'address', b.address, 'contact_phone', b.contact_phone,
               'operating_hours', b.operating_hours, 'is_active', b.is_active,
               'supports_delivery', b.supports_delivery, 'supports_pickup', b.supports_pickup,
               'delivery_fee', b.delivery_fee, 'daily_sales_target', b.daily_sales_target,
               'latitude', to_jsonb(b) -> 'latitude', 'longitude', to_jsonb(b) -> 'longitude',
               'is_warehouse', coalesce((to_jsonb(b) ->> 'is_warehouse')::boolean, false))
             order by b.name)
      from public.branches b
      where v_staff.role = 'owner' or b.id = v_staff.branch_id), '[]'::jsonb)
  );
end;
$$;
revoke all on function public.get_business_settings() from public, anon;
grant execute on function public.get_business_settings() to authenticated;

-- -----------------------------------------------------------------------------
-- 6. Owner-only writes (audited)
-- -----------------------------------------------------------------------------
-- p_settings keys (all optional; a key present with JSON null clears the value):
--   restock_threshold_default, stock_low_ratio, stock_plenty_ratio, sales_low_ratio,
--   sales_high_ratio, default_daily_sales_target, healthy_margin_percent, expiry_alert_days
create or replace function public.owner_update_business_settings(p_settings jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner public.staff_members;
  v_old public.business_settings;
  v_new public.business_settings;
  k text;
  allowed text[] := array['restock_threshold_default', 'stock_low_ratio', 'stock_plenty_ratio', 'sales_low_ratio',
                          'sales_high_ratio', 'default_daily_sales_target', 'healthy_margin_percent', 'expiry_alert_days'];
begin
  v_owner := public._require_owner();
  if p_settings is null or jsonb_typeof(p_settings) <> 'object' then
    raise exception 'Settings must be an object.';
  end if;
  for k in select jsonb_object_keys(p_settings) loop
    if not (k = any(allowed)) then raise exception 'Unknown setting: %', k; end if;
    if jsonb_typeof(p_settings -> k) not in ('number', 'null') then raise exception 'Setting % must be a number or empty.', k; end if;
  end loop;

  insert into public.business_settings (id) values ('default') on conflict (id) do nothing;
  select * into v_old from public.business_settings where id = 'default' for update;
  v_new := v_old;
  if p_settings ? 'restock_threshold_default' then
    v_new.restock_threshold_default := (p_settings ->> 'restock_threshold_default')::numeric::int; end if;
  if p_settings ? 'stock_low_ratio' then v_new.stock_low_ratio := (p_settings ->> 'stock_low_ratio')::numeric; end if;
  if p_settings ? 'stock_plenty_ratio' then v_new.stock_plenty_ratio := (p_settings ->> 'stock_plenty_ratio')::numeric; end if;
  if p_settings ? 'sales_low_ratio' then v_new.sales_low_ratio := (p_settings ->> 'sales_low_ratio')::numeric; end if;
  if p_settings ? 'sales_high_ratio' then v_new.sales_high_ratio := (p_settings ->> 'sales_high_ratio')::numeric; end if;
  if p_settings ? 'default_daily_sales_target' then
    v_new.default_daily_sales_target := (p_settings ->> 'default_daily_sales_target')::numeric; end if;
  if p_settings ? 'healthy_margin_percent' then
    v_new.healthy_margin_percent := (p_settings ->> 'healthy_margin_percent')::numeric; end if;
  if p_settings ? 'expiry_alert_days' then
    v_new.expiry_alert_days := (p_settings ->> 'expiry_alert_days')::numeric::int; end if;

  begin
    update public.business_settings set
      restock_threshold_default = v_new.restock_threshold_default,
      stock_low_ratio = v_new.stock_low_ratio,
      stock_plenty_ratio = v_new.stock_plenty_ratio,
      sales_low_ratio = v_new.sales_low_ratio,
      sales_high_ratio = v_new.sales_high_ratio,
      default_daily_sales_target = v_new.default_daily_sales_target,
      healthy_margin_percent = v_new.healthy_margin_percent,
      expiry_alert_days = v_new.expiry_alert_days,
      carried_over = false,
      updated_at = now(),
      updated_by = v_owner.firebase_uid
    where id = 'default';
  exception when check_violation then
    raise exception 'A setting is out of range (ratios: low must be below plenty / high; margin 1-99%%; threshold 0-100,000; targets above 0; expiry alerts 1-365 days).';
  end;

  perform public._write_audit(v_owner.firebase_uid, null, 'business.settings_updated', 'business_settings', 'default',
    jsonb_build_object('before', to_jsonb(v_old) - 'updated_at' - 'updated_by',
                       'after', p_settings));
  return public.get_business_settings();
end;
$$;
revoke all on function public.owner_update_business_settings(jsonb) from public, anon;
grant execute on function public.owner_update_business_settings(jsonb) to authenticated;

-- Create (p_branch_id null) or update a branch's customer-facing details.
create or replace function public.owner_save_branch(
  p_branch_id uuid,
  p_name text,
  p_address text,
  p_contact_phone text,
  p_operating_hours text,
  p_delivery_fee numeric,
  p_daily_sales_target numeric,
  p_supports_delivery boolean,
  p_supports_pickup boolean,
  p_is_active boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner public.staff_members;
  v_id uuid := p_branch_id;
  v_name text := trim(coalesce(p_name, ''));
  v_before jsonb;
begin
  v_owner := public._require_owner();
  if v_name = '' or length(v_name) > 80 then raise exception 'Enter the branch name (up to 80 characters).'; end if;
  if p_delivery_fee is null then raise exception 'Enter the delivery fee (0 if delivery is free).'; end if;
  if p_delivery_fee < 0 or p_delivery_fee > 100000 then raise exception 'Delivery fee must be between 0 and 100,000.'; end if;
  if p_daily_sales_target is not null and p_daily_sales_target <= 0 then
    raise exception 'A daily sales target must be more than 0 (leave it empty for none).';
  end if;
  if length(coalesce(p_address, '')) > 300 or length(coalesce(p_contact_phone, '')) > 40
     or length(coalesce(p_operating_hours, '')) > 200 then
    raise exception 'Address, phone or hours is too long.';
  end if;

  if v_id is null then
    insert into public.branches (name, address, contact_phone, operating_hours, delivery_fee, daily_sales_target,
                                 supports_delivery, supports_pickup, is_active)
    values (v_name, nullif(trim(coalesce(p_address, '')), ''), nullif(trim(coalesce(p_contact_phone, '')), ''),
            nullif(trim(coalesce(p_operating_hours, '')), ''), p_delivery_fee, p_daily_sales_target,
            coalesce(p_supports_delivery, false), coalesce(p_supports_pickup, false), coalesce(p_is_active, true))
    returning id into v_id;
  else
    select to_jsonb(b) into v_before from public.branches b where id = v_id for update;
    if v_before is null then raise exception 'That branch could not be found.'; end if;
    update public.branches set
      name = v_name,
      address = nullif(trim(coalesce(p_address, '')), ''),
      contact_phone = nullif(trim(coalesce(p_contact_phone, '')), ''),
      operating_hours = nullif(trim(coalesce(p_operating_hours, '')), ''),
      delivery_fee = p_delivery_fee,
      daily_sales_target = p_daily_sales_target,
      supports_delivery = coalesce(p_supports_delivery, supports_delivery),
      supports_pickup = coalesce(p_supports_pickup, supports_pickup),
      is_active = coalesce(p_is_active, is_active)
    where id = v_id;
  end if;

  perform public._write_audit(v_owner.firebase_uid, v_id, case when p_branch_id is null then 'branch.created' else 'branch.updated' end,
    'branch', v_id::text, jsonb_build_object('before', v_before,
      'after', (select to_jsonb(b) from public.branches b where b.id = v_id)));
  return jsonb_build_object('id', v_id);
exception
  when unique_violation then
    raise exception 'Another branch already has the name %.', v_name;
  when check_violation then
    raise exception 'A warehouse cannot take deliveries or pickups (or a value is out of range).';
end;
$$;
revoke all on function public.owner_save_branch(uuid, text, text, text, text, numeric, numeric, boolean, boolean, boolean) from public, anon;
grant execute on function public.owner_save_branch(uuid, text, text, text, text, numeric, numeric, boolean, boolean, boolean) to authenticated;

commit;


-- >>>>>>>>>> 20261019000000_rate_limits.sql <<<<<<<<<<
-- =============================================================================
-- Melai Nuts — Migration 20261019000000: rate limits for voucher codes and orders
-- =============================================================================
-- Run after 20261018000000_business_settings.sql. Idempotent, one transaction.
--
-- WHY
--   A modified client (or a script using the public anon key + a Firebase token)
--   could try voucher codes in a loop, or create orders in a burst. Firebase
--   App Check (see docs/APP_CHECK.md) makes such clients harder to build; these
--   limits are enforced by the database whatever the client is.
--
-- WHAT
--   * Voucher codes: a code must be "registered" by public.register_voucher_attempt()
--     before a cart may use it (a carts trigger checks that). Registering is limited
--     to 10 codes per account per 15 minutes. The registration is committed on its
--     own, so failed guesses count too (a failed cart sync rolls back, a registration
--     does not). A registration stays valid for 24 hours.
--   * Orders: at most 5 new customer orders per account per 10 minutes. Replaying an
--     idempotency key returns the existing order and is not counted; POS sales are
--     not affected.
--   The numbers are technical security limits (not business data), kept in one
--   function, public._rate_limits().
--
-- SCOPE
--   The limits apply to requests coming through the Data API (session user
--   `authenticator`, i.e. the app and anything using its keys). SQL run by the
--   database owner (repairs, the admin portal's own role) is not limited. Tests can
--   force them on with:  select set_config('melai.force_rate_limits', 'on', true);
--   (turning them ON is the only thing that setting can do).
-- =============================================================================
begin;

create table if not exists public.rate_limit_events (
  id bigserial primary key,
  firebase_uid text not null,
  action text not null check (action in ('voucher')),
  subject text,
  created_at timestamptz not null default now()
);
create index if not exists rate_limit_events_lookup_idx
  on public.rate_limit_events (firebase_uid, action, created_at desc);
alter table public.rate_limit_events enable row level security;
revoke all on public.rate_limit_events from anon, authenticated;
revoke all on sequence public.rate_limit_events_id_seq from anon, authenticated;

create or replace function public._rate_limits()
returns jsonb
language sql
immutable
as $$
  select jsonb_build_object(
    'voucher_max', 10, 'voucher_window_minutes', 15, 'voucher_valid_hours', 24,
    'order_max', 5, 'order_window_minutes', 10)
$$;

create or replace function public._rate_limit_applies()
returns boolean
language sql
stable
as $$
  select session_user = 'authenticator'
      or coalesce(current_setting('melai.force_rate_limits', true), '') = 'on'
$$;

-- -----------------------------------------------------------------------------
-- Voucher codes
-- -----------------------------------------------------------------------------
create or replace function public.register_voucher_attempt(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid text := public.current_firebase_uid();
  v_code text := nullif(upper(trim(coalesce(p_code, ''))), '');
  v_lim jsonb := public._rate_limits();
  v_max int := (v_lim ->> 'voucher_max')::int;
  v_window int := (v_lim ->> 'voucher_window_minutes')::int;
  v_used int;
begin
  if v_uid is null then raise exception 'Please sign in to use a voucher.'; end if;
  if v_code is null or length(v_code) > 64 then raise exception 'Enter a voucher code.'; end if;

  -- One account's attempts are counted one at a time (no race past the limit).
  perform pg_advisory_xact_lock(hashtext('melai:rl:voucher:' || v_uid));
  select count(*) into v_used from public.rate_limit_events
   where firebase_uid = v_uid and action = 'voucher'
     and created_at > now() - make_interval(mins => v_window);
  if public._rate_limit_applies() and v_used >= v_max then
    raise exception 'Too many voucher attempts. Please wait % minutes and try again.', v_window;
  end if;

  insert into public.rate_limit_events (firebase_uid, action, subject) values (v_uid, 'voucher', v_code);
  delete from public.rate_limit_events where firebase_uid = v_uid and created_at < now() - interval '2 days';
  return jsonb_build_object('ok', true, 'remaining', greatest(v_max - v_used - 1, 0));
end;
$$;
revoke all on function public.register_voucher_attempt(text) from public, anon;
grant execute on function public.register_voucher_attempt(text) to authenticated;

create or replace function public._trg_carts_voucher_rate_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid text := public.current_firebase_uid();
  v_code text := nullif(upper(trim(coalesce(new.voucher_code, ''))), '');
  v_valid int := (public._rate_limits() ->> 'voucher_valid_hours')::int;
begin
  if v_code is null or v_uid is null or not public._rate_limit_applies() then return new; end if;
  if tg_op = 'UPDATE' and v_code is not distinct from nullif(upper(trim(coalesce(old.voucher_code, ''))), '') then
    return new;   -- the same code as before (every cart sync re-sends it)
  end if;
  if not exists (
    select 1 from public.rate_limit_events
     where firebase_uid = v_uid and action = 'voucher' and subject = v_code
       and created_at > now() - make_interval(hours => v_valid)) then
    raise exception 'Please enter the voucher code again.';
  end if;
  return new;
end;
$$;
revoke all on function public._trg_carts_voucher_rate_limit() from public, anon, authenticated;

drop trigger if exists carts_voucher_rate_limit on public.carts;
create trigger carts_voucher_rate_limit
  before insert or update of voucher_code on public.carts
  for each row execute function public._trg_carts_voucher_rate_limit();

-- -----------------------------------------------------------------------------
-- Orders
-- -----------------------------------------------------------------------------
create or replace function public._trg_orders_rate_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid text := public.current_firebase_uid();
  v_lim jsonb := public._rate_limits();
  v_recent int;
begin
  if not public._rate_limit_applies() then return new; end if;
  if coalesce(current_setting('app.pos_sale', true), '') = '1' then return new; end if;   -- POS sale
  if v_uid is null or new.firebase_uid is distinct from v_uid then return new; end if;

  perform pg_advisory_xact_lock(hashtext('melai:rl:order:' || v_uid));
  select count(*) into v_recent from public.orders
   where firebase_uid = v_uid
     and created_at > now() - make_interval(mins => (v_lim ->> 'order_window_minutes')::int);
  if v_recent >= (v_lim ->> 'order_max')::int then
    raise exception 'Too many orders in a short time. Please wait a few minutes and try again.';
  end if;
  return new;
end;
$$;
revoke all on function public._trg_orders_rate_limit() from public, anon, authenticated;

drop trigger if exists orders_rate_limit on public.orders;
create trigger orders_rate_limit
  before insert on public.orders
  for each row execute function public._trg_orders_rate_limit();

commit;


-- >>>>>>>>>> 20261020000000_staff_orders_variant_ids.sql <<<<<<<<<<
-- =============================================================================
-- Melai Nuts — Migration 20261020000000: order items carry their variant id
-- =============================================================================
-- Run after 20261019000000_rate_limits.sql. Idempotent, one transaction.
-- staff_list_orders() now returns variant_id and product_id for every order
-- item, so the staff app can offer COUNTER RETURNS (staff_pos_return /
-- staff_receive_returned_items need the variant of each returned line).
-- Same function otherwise (same scoping, same columns).
-- =============================================================================
begin;

create or replace function public.staff_list_orders(
  p_branch_id uuid default null,
  p_statuses text[] default null,
  p_since timestamptz default null,
  p_limit int default 100,
  p_order_id text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_staff public.staff_members;
  v_branch uuid;
begin
  v_staff := public._require_staff();
  v_branch := case when v_staff.role = 'owner' then p_branch_id else v_staff.branch_id end;
  if v_branch is null then raise exception 'Please choose a branch first.'; end if;

  return (
    select coalesce(jsonb_agg(x.j order by x.created_at desc), '[]'::jsonb)
    from (
      select o.created_at,
        jsonb_build_object(
          'id', o.id, 'created_at', o.created_at, 'status', o.status,
          'branch_id', o.branch_id, 'branch_name', o.branch_name, 'is_delivery', o.is_delivery,
          'subtotal', o.subtotal, 'discount', o.discount, 'delivery_fee', o.delivery_fee, 'total', o.total,
          'payment_method', o.payment_method, 'points_earned', o.points_earned,
          'customer_notes', o.customer_notes, 'contact_phone', o.contact_phone,
          'delivery_address_text', o.delivery_address_text,
          'rider_name', o.rider_name, 'eta_label', o.eta_label,
          'customer_name', case when o.firebase_uid = 'walk-in' then null else nullif(cp.full_name, '') end,
          'is_pos', (ps.order_id is not null),
          'cashier_name', nullif(ps.staff_name, ''),
          'cash_received', ps.cash_received, 'change_given', ps.change_given,
          'items', (select coalesce(jsonb_agg(jsonb_build_object(
                      'variant_id', i.variant_id, 'product_id', i.product_id,
                      'product_name', i.product_name, 'variant_label', i.variant_label,
                      'quantity', i.quantity, 'unit_price', i.unit_price)), '[]'::jsonb)
                    from public.order_items i where i.order_id = o.id),
          'payment', (select jsonb_build_object('id', pay.id, 'method', pay.method, 'status', pay.status,
                                                'reference_number', pay.reference_number, 'amount', pay.amount)
                      from public.payments pay where pay.order_id = o.id limit 1),
          'refund_summary', public._order_refund_json(o.id)
        ) as j
      from public.orders o
      left join public.customer_profiles cp on cp.firebase_uid = o.firebase_uid
      left join public.pos_sales ps on ps.order_id = o.id
      where o.branch_id = v_branch
        and (p_statuses is null or o.status = any(p_statuses))
        and (p_since is null or o.created_at >= p_since)
        and (p_order_id is null or o.id = p_order_id)
      order by o.created_at desc
      limit least(greatest(coalesce(p_limit, 100), 1), 300)
    ) x
  );
end;
$$;

grant execute on function public.staff_list_orders(uuid, text[], timestamptz, int, text) to authenticated;

commit;


-- >>>>>>>>>> 20261021000000_push_notifications.sql <<<<<<<<<<
-- =============================================================================
-- Melai Nuts — Migration 20261021000000: push notifications (server-triggered)
-- =============================================================================
-- Run after 20261020000000_staff_orders_variant_ids.sql. Idempotent, one transaction.
--
-- Pushes are created ONLY by the database, never by an app:
--   * every row added to public.notifications (customers: order status, refund
--     decisions, ...) and to public.staff_notifications (branch staff: new orders,
--     low / out of stock, refunds to review, expiring batches) is copied into
--     public.push_outbox for its recipient;
--   * the Edge Function `push-dispatch` (supabase/functions/push-dispatch) sends the
--     outbox through Firebase Cloud Messaging and marks rows sent; it runs on a
--     schedule (docs/PUSH_NOTIFICATIONS.md).
--   * expiring batches: public.enqueue_expiring_batch_alerts() (run daily by the
--     same schedule) notifies branch staff once per batch, within the owner's
--     business_settings.expiry_alert_days (Not set = no expiry alerts).
-- Apps only register / remove their own device token.
-- =============================================================================
begin;

-- -----------------------------------------------------------------------------
-- 1. Device tokens (one row per device; a device belongs to one account)
-- -----------------------------------------------------------------------------
create table if not exists public.device_push_tokens (
  token text primary key check (char_length(token) between 20 and 4096),
  firebase_uid text not null,
  platform text not null check (platform in ('android', 'ios', 'web', 'macos', 'windows')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists device_push_tokens_uid_idx on public.device_push_tokens (firebase_uid);
alter table public.device_push_tokens enable row level security;
revoke all on public.device_push_tokens from anon, authenticated;

create or replace function public.register_push_token(p_token text, p_platform text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid text := public.current_firebase_uid();
  v_token text := trim(coalesce(p_token, ''));
begin
  if v_uid is null then raise exception 'Please sign in first.'; end if;
  if char_length(v_token) < 20 or char_length(v_token) > 4096 then raise exception 'Invalid device token.'; end if;
  if p_platform not in ('android', 'ios', 'web', 'macos', 'windows') then raise exception 'Unknown platform.'; end if;
  -- A token moves to whoever signs in on that device (the previous account stops getting its pushes).
  insert into public.device_push_tokens (token, firebase_uid, platform)
  values (v_token, v_uid, p_platform)
  on conflict (token) do update set firebase_uid = excluded.firebase_uid, platform = excluded.platform, updated_at = now();
end;
$$;
revoke all on function public.register_push_token(text, text) from public, anon;
grant execute on function public.register_push_token(text, text) to authenticated;

create or replace function public.unregister_push_token(p_token text)
returns void
language sql
security definer
set search_path = public
as $$
  delete from public.device_push_tokens
   where token = trim(coalesce(p_token, '')) and firebase_uid = public.current_firebase_uid()
$$;
revoke all on function public.unregister_push_token(text) from public, anon;
grant execute on function public.unregister_push_token(text) to authenticated;

-- -----------------------------------------------------------------------------
-- 2. Outbox (service role only)
-- -----------------------------------------------------------------------------
create table if not exists public.push_outbox (
  id bigserial primary key,
  firebase_uid text not null,
  kind text not null,
  title text not null,
  body text not null default '',
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  sent_at timestamptz,
  attempts int not null default 0,
  last_error text
);
create index if not exists push_outbox_unsent_idx on public.push_outbox (created_at) where sent_at is null;
alter table public.push_outbox enable row level security;
revoke all on public.push_outbox from anon, authenticated;
revoke all on sequence public.push_outbox_id_seq from anon, authenticated;

create or replace function public._trg_push_from_customer_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  begin
    insert into public.push_outbox (firebase_uid, kind, title, body, data)
    values (new.firebase_uid, 'customer.' || coalesce(new.category, 'general'), new.title, coalesce(new.body, ''),
            jsonb_build_object('notification_id', new.id, 'category', new.category));
  exception when others then
    raise warning 'push outbox insert failed: %', sqlerrm;   -- never block the business change
  end;
  return new;
end;
$$;
drop trigger if exists notifications_push on public.notifications;
create trigger notifications_push after insert on public.notifications
  for each row execute function public._trg_push_from_customer_notification();

create or replace function public._trg_push_from_staff_notification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  begin
    insert into public.push_outbox (firebase_uid, kind, title, body, data)
    values (new.recipient_uid, 'staff.' || coalesce(new.category, 'general'), new.title, coalesce(new.body, ''),
            jsonb_build_object('notification_id', new.id, 'category', new.category, 'reference', new.reference,
                               'branch_id', new.branch_id));
  exception when others then
    raise warning 'push outbox insert failed: %', sqlerrm;
  end;
  return new;
end;
$$;
drop trigger if exists staff_notifications_push on public.staff_notifications;
create trigger staff_notifications_push after insert on public.staff_notifications
  for each row execute function public._trg_push_from_staff_notification();

revoke all on function public._trg_push_from_customer_notification() from public, anon, authenticated;
revoke all on function public._trg_push_from_staff_notification() from public, anon, authenticated;

-- What push-dispatch sends next (service role only): unsent, not given up on.
create or replace function public.push_outbox_claim(p_limit int default 100)
returns jsonb
language sql
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', o.id, 'firebase_uid', o.firebase_uid, 'kind', o.kind, 'title', o.title, 'body', o.body, 'data', o.data,
           'tokens', coalesce((select jsonb_agg(t.token) from public.device_push_tokens t where t.firebase_uid = o.firebase_uid), '[]'::jsonb))
         order by o.id), '[]'::jsonb)
  from (select * from public.push_outbox
         where sent_at is null and attempts < 5 and created_at > now() - interval '2 days'
         order by id limit least(greatest(coalesce(p_limit, 100), 1), 500)) o
$$;

-- p_result: [{"id": 1, "ok": true} | {"id": 2, "ok": false, "error": "...", "dead_tokens": ["..."]}]
create or replace function public.push_outbox_report(p_result jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  r jsonb;
begin
  for r in select * from jsonb_array_elements(coalesce(p_result, '[]'::jsonb)) loop
    if coalesce((r ->> 'ok')::boolean, false) then
      update public.push_outbox set sent_at = now(), attempts = attempts + 1, last_error = null where id = (r ->> 'id')::bigint;
    else
      update public.push_outbox set attempts = attempts + 1, last_error = left(coalesce(r ->> 'error', 'failed'), 300)
       where id = (r ->> 'id')::bigint;
    end if;
    delete from public.device_push_tokens
     where token in (select jsonb_array_elements_text(coalesce(r -> 'dead_tokens', '[]'::jsonb)));
  end loop;
  delete from public.push_outbox where created_at < now() - interval '14 days';
end;
$$;
revoke all on function public.push_outbox_claim(int) from public, anon, authenticated;
revoke all on function public.push_outbox_report(jsonb) from public, anon, authenticated;
grant execute on function public.push_outbox_claim(int) to service_role;
grant execute on function public.push_outbox_report(jsonb) to service_role;

-- -----------------------------------------------------------------------------
-- 3. Expiring batches (owner setting; Not set = no alerts)
-- -----------------------------------------------------------------------------
-- business_settings.expiry_alert_days is created by 20261018000000 (owner edits it on
-- Business settings); this guard keeps the migration runnable on its own.
alter table public.business_settings add column if not exists expiry_alert_days int;

create or replace function public.enqueue_expiring_batch_alerts()
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  v_days int := (select expiry_alert_days from public.business_settings where id = 'default');
  b record;
  n int := 0;
begin
  if v_days is null then return 0; end if;
  for b in
    select ib.id, ib.branch_id, ib.expiration_date, ib.quantity,
           p.name || ' (' || pv.label || ')' as item
      from public.inventory_batches ib
      join public.product_variants pv on pv.id = ib.variant_id
      join public.products p on p.id = pv.product_id
     where ib.quantity > 0
       and ib.expiration_date <= current_date + v_days
       and not exists (select 1 from public.staff_notifications sn where sn.reference = 'expiry:' || ib.id::text)
  loop
    perform public._notify_staff(b.branch_id, 'inventory',
      case when b.expiration_date < current_date then 'Expired: ' else 'Expiring soon: ' end || b.item,
      b.quantity || ' unit(s), batch expires ' || to_char(b.expiration_date, 'Mon DD, YYYY') || '.',
      'expiry:' || b.id::text, 'inventory');
    n := n + 1;
  end loop;
  return n;
end;
$$;
revoke all on function public.enqueue_expiring_batch_alerts() from public, anon, authenticated;
grant execute on function public.enqueue_expiring_batch_alerts() to service_role;

commit;


